    // regressed back to the older (revision 2) projection.
    await act(async () => {
      await Promise.resolve();
      await Promise.resolve();
    });

    expect(captured.activeSessionId).toBe(SESSION_A1);
    expect(captured.userId).toBe(ACCOUNT_A1);
