      deviceId: 'dev-1',
      accounts: [],
      activeAccountId: null,
      revision: 2,
      updatedAt: Date.now(),
    };

    // Simulates BOTH device accounts being signed out from another
    // tab/device — no `logout()`/`logoutAll()` call happens on THIS
    // instance, only the remote push.
    act(() => {
      fake.push(pushed);
    });

