let capturedContext: OxyContextState | null = null;

function Capture() {
  capturedContext = useOxy();
  return null;
}

function renderProvider(oxyServices: unknown): RenderResult {
  const queryClient = new QueryClient({ defaultOptions: { queries: { retry: false } } });
