    } },
cache: { clear: jest.fn() },
apps: { getPublic: jest.fn(async () => ({ id: 'registered-fixture', name: 'Registered Fixture', type: 'first_party', isOfficial: false, isInternal: false, scopes: [] })) },
devices: { mintToken: jest.fn(async () => ({
